-- FRACTALES ACADEMY V4.5 | SCRIPT 08 ACTUALIZADO
-- Basado en la migracion 08 original, sin cambios a datos academicos.
-- Requiere 07 superado, base recuperable y aplicacion sin escrituras.
-- Advertencia: elimina dos objetos AUXILIARES de migracion, no datos academicos.
-- Conservar el archivo original y ensayar en una copia restaurada.
-- MANUAL, separado. No retira tablas de negocio ni elimina datos reales.
SET NOCOUNT ON;SET XACT_ABORT ON;
DECLARE @BaseEsperada sysname=N'FractalesAcademy';
DECLARE @Confirmacion nvarchar(80)=N'FINALIZAR V4.5 VERIFICADA';
IF DB_NAME()<>@BaseEsperada THROW 54500,'Confirma base y servidor.',1;
IF @Confirmacion<>N'FINALIZAR V4.5 VERIFICADA' THROW 54508,'Revisa 07 y confirma FINALIZAR V4.5 VERIFICADA.',1;
IF (SELECT COUNT(*) FROM dbo.CONTROL_MIGRACION WHERE SCRIPT IN('V45_01_PREPARAR','V45_02_MIGRAR','V45_03_NOMBRES','V45_04_PAPELERA','V45_05_AUDITORIA','V45_06_RESTRICCIONES'))<>6 THROW 54508,'Faltan etapas previas.',1;
BEGIN TRY BEGIN TRAN;
IF NOT EXISTS(SELECT 1 FROM dbo.CONTROL_MIGRACION WITH(UPDLOCK,HOLDLOCK) WHERE SCRIPT='V45_08_FINALIZAR')
BEGIN
 -- BEGIN VERIFICACION V45
-- SOLO LECTURA; aplicar con todas las escrituras detenidas.
SET NOCOUNT ON;
IF OBJECT_ID('dbo.MIGRACION_INTEGRIDAD_V45') IS NULL THROW 54507,'Falta linea base temporal. Despues de 08 usar 09.',1;
IF (SELECT COUNT_BIG(*) FROM dbo.MIGRACION_INTEGRIDAD_V45 WHERE TABLA=N'ALUMNO')<>(SELECT COUNT_BIG(*) FROM dbo.[ALUMNO] r) OR EXISTS(SELECT 1 FROM dbo.[ALUMNO] r LEFT JOIN dbo.MIGRACION_INTEGRIDAD_V45 b ON b.TABLA=N'ALUMNO' AND b.CLAVE=(SELECT r.[DNI_ALUMNO] AS [DNI_ALUMNO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) WHERE (b.CLAVE IS NULL OR b.HUELLA<>HASHBYTES('SHA2_256',(SELECT r.[DNI_ALUMNO] AS [DNI_ALUMNO],r.[NOMBRE_COMPLETO] AS [NOMBRE_COMPLETO],r.[CORREO] AS [CORREO],r.[FECHA_NACIMIENTO] AS [FECHA_NACIMIENTO],r.[CELULAR] AS [CELULAR],r.[DIRECCION] AS [DIRECCION],r.[NOMBRE_APODERADO] AS [NOMBRE_APODERADO],r.[DNI_APODERADO] AS [DNI_APODERADO],r.[CELULAR_APODERADO] AS [CELULAR_APODERADO],r.[CORREO_APODERADO] AS [CORREO_APODERADO],r.[ID_PARENTESCO] AS [ID_PARENTESCO],r.[ID_CARRERA] AS [ID_CARRERA],r.[ES_PRUEBA] AS [ES_PRUEBA] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)))) THROW 54507,N'Datos distintos en ALUMNO; no retirar estructuras.',1;
IF (SELECT COUNT_BIG(*) FROM dbo.MIGRACION_INTEGRIDAD_V45 WHERE TABLA=N'ESTADO_ALUMNO')<>(SELECT COUNT_BIG(*) FROM dbo.[ESTADO_ALUMNO] r) OR EXISTS(SELECT 1 FROM dbo.[ESTADO_ALUMNO] r LEFT JOIN dbo.MIGRACION_INTEGRIDAD_V45 b ON b.TABLA=N'ESTADO_ALUMNO' AND b.CLAVE=(SELECT r.[DNI_ALUMNO] AS [DNI_ALUMNO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) WHERE (b.CLAVE IS NULL OR b.HUELLA<>HASHBYTES('SHA2_256',(SELECT r.[DNI_ALUMNO] AS [DNI_ALUMNO],r.[ACTIVO] AS [ACTIVO],r.[ACCESO_ACTIVO_ANTERIOR] AS [ACCESO_ACTIVO_ANTERIOR],r.[MOTIVO] AS [MOTIVO],r.[ID_USUARIO_RESPONSABLE] AS [ID_USUARIO_RESPONSABLE],r.[FECHA_EVENTO] AS [FECHA_EVENTO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)))) THROW 54507,N'Datos distintos en ESTADO_ALUMNO; no retirar estructuras.',1;
