 AS [ID_USUARIO_RESPONSABLE],r.[MOTIVO] AS [MOTIVO],r.[FECHA_EVENTO] AS [FECHA_EVENTO] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)))) THROW 54507,N'Datos distintos en AUDITORIA_SISTEMA; no retirar estructuras.',1;
