-- VERIFICACION EXTRA V4.5: DBCC puede devolver filas de infracciones sin THROW.
-- Capturamos su resultado y rechazamos el retiro si existen violaciones.
DECLARE @Incumplimientos08 TABLE
(
    Tabla nvarchar(256) NULL,
    Restriccion nvarchar(256) NULL,
    Condicion nvarchar(max) NULL
);
INSERT INTO @Incumplimientos08 (Tabla, Restriccion, Condicion)
EXEC (N'DBCC CHECKCONSTRAINTS WITH ALL_CONSTRAINTS, ALL_ERRORMSGS, NO_INFOMSGS;');
IF EXISTS (SELECT 1 FROM @Incumplimientos08)
    THROW 54507, 'Hay restricciones incumplidas: no se retiran objetos auxiliares.', 1;

 IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE referenced_object_id=OBJECT_ID('dbo.MIGRACION_INTEGRIDAD_V45')) THROW 54508,'Dependencia adicional del control temporal.',1;
 DROP TABLE dbo.MIGRACION_INTEGRIDAD_V45;
 DROP FUNCTION dbo.FN_V45_NORMALIZAR_JSON;
 INSERT dbo.CONTROL_MIGRACION(SCRIPT) VALUES('V45_08_FINALIZAR');
END;COMMIT;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;THROW;END CATCH;


IF NOT EXISTS (SELECT 1 FROM dbo.CONTROL_MIGRACION WHERE SCRIPT = 'V45_08_FINALIZAR')
    THROW 54508, 'No se encontro confirmacion de finalizacion V4.5.', 1;
SELECT N'SCRIPT 08 COMPLETADO' AS RESULTADO, DB_NAME() AS BASE_DATOS;
